record User(int id, String name, String email) {}
static Optional<User> findById(Connection conn, int id) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE id=?")) {
    ps.setInt(1, id);
    try (ResultSet rs = ps.executeQuery()) { if (rs.next()) return Optional.of(new User(rs.getInt(1), rs.getString(2), rs.getString(3))); return Optional.empty(); }
  }
}

static List<User> findAll(Connection conn) throws SQLException {
  List<User> result = new ArrayList<>();
  try (Statement s = conn.createStatement(); ResultSet rs = s.executeQuery("SELECT * FROM users")) {
    while (rs.next()) result.add(new User(rs.getInt(1), rs.getString(2), rs.getString(3)));
  }
  return result;
}
findAll(conn).forEach(System.out::println);

static Optional<User> findByEmail(Connection conn, String email) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE email=?")) {
    ps.setString(1, email);
    try (ResultSet rs = ps.executeQuery()) { if (rs.next()) return Optional.of(mapRow(rs)); return Optional.empty(); }
  }
}

