static List<User> findPage(Connection conn, int limit, int offset) throws SQLException {
  List<User> result = new ArrayList<>();
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users ORDER BY id LIMIT ? OFFSET ?")) {
    ps.setInt(1, limit); ps.setInt(2, offset);
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) result.add(mapRow(rs)); }
  }
  return result;
}

class UserNotFoundException extends RuntimeException {
  UserNotFoundException(int id) { super("Uzytkownik o id=" + id + " nie istnieje"); }
}
static User findByIdOrThrow(Connection conn, int id) throws SQLException {
  return findById(conn, id).orElseThrow(() -> new UserNotFoundException(id));
}

static List<User> findByIds(Connection conn, List<Integer> ids) throws SQLException {
  String placeholders = String.join(",", Collections.nCopies(ids.size(), "?"));
  List<User> result = new ArrayList<>();
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE id IN (" + placeholders + ")")) {
    for (int i = 0; i < ids.size(); i++) ps.setInt(i + 1, ids.get(i));
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) result.add(mapRow(rs)); }
  }
  return result;
}

