static void printAllPages(Connection conn, int pageSize) throws SQLException {
  int offset = 0;
  List<User> page;
  do {
    page = findPage(conn, pageSize, offset);
    System.out.println("Strona offset=" + offset + ": " + page);
    offset += pageSize;
  } while (!page.isEmpty());
}

static List<User> search(Connection conn, String term) throws SQLException {
  String pattern = "%" + term + "%";
  List<User> result = new ArrayList<>();
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE name LIKE ? OR email LIKE ?")) {
    ps.setString(1, pattern); ps.setString(2, pattern);
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) result.add(mapRow(rs)); }
  }
  return result;
}

static List<User> findFiltered(Connection conn, String nameContains, String emailDomain) throws SQLException {
  List<String> conditions = new ArrayList<>();
  List<Object> params = new ArrayList<>();
  if (nameContains != null) { conditions.add("name LIKE ?"); params.add("%" + nameContains + "%"); }
  if (emailDomain != null) { conditions.add("email LIKE ?"); params.add("%" + emailDomain); }
  String sql = "SELECT * FROM users" + (conditions.isEmpty() ? "" : " WHERE " + String.join(" AND ", conditions));
  try (PreparedStatement ps = conn.prepareStatement(sql)) {
    for (int i = 0; i < params.size(); i++) ps.setObject(i + 1, params.get(i));
    List<User> result = new ArrayList<>();
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) result.add(mapRow(rs)); }
    return result;
  }
}

